function reconcile(list, confirmed) {
  const next = [];
  for (const item of list) {
    if (item.id === confirmed.id) {
      next.push({ ...item, ...confirmed });
    } else {
      next.push(item);
    }
  }
  next.push({ id: confirmed.id, body: confirmed.body, status: confirmed.status });
  return next;
}

