// resolves when the queued job confirms; powers every pending spinner
async function awaitConfirmation(statusUrl) {
  while (true) {
    const res = await fetch(statusUrl);
    const body = await res.json();
    if (body.status === 'confirmed') {
      return body.result;
    }
    await sleep(500);
  }
}
